const own=[{id:'w-worker',name:'Persona sintética',canReport:true,canAttendance:true}],context={projectId:'p-a',scope:'a'.repeat(64)};
const storage=()=>{const values=new Map();return {values,get length(){return values.size;},key:index=>[...values.keys()][index]??null,getItem:key=>values.get(key)??null,setItem:(key,value)=>values.set(key,value),removeItem:key=>values.delete(key)};};
async function prepared({measured=false}={}){const f=fieldExecutionFixture({measured}),issued=await f.issue(),snapshot=await f.operations.executionView(f.session('worker'),context),fields={mandateId:issued.mandate.id,lines:[{materialId:'material-a',quantity:'1.001'}],progress:null,evidenceIds:[],reason:' Cantidades realizadas\r\nen esta tarea. '},reportId=randomUUID();return {f,issued,snapshot,fields,reportId,tasks:[f.state.task],now:Date.parse(f.state.now)};}
