 const p=await prepared(),a=await attempt(p),out=await p.f.operations.save(p.f.session('worker'),a.command),first=executionReportResult(out,a);assert.equal(first.state,'RECORDED');assert.equal(first.view.movements[0].quantity,'1.001');assert.equal(p.f.movements().length,1);assert.equal(p.f.state.project.metadata.materialInventory.materials[0].balance,'8.999');
