 for(const edit of [v=>v.execution.reportId=randomUUID(),v=>v.execution.workerId='other',v=>v.execution.mandateRevision=2,v=>v.execution.movements[0].lineId='other-line',v=>v.execution.movements[0].quantity='1.002',v=>v.requestDigest='f'.repeat(64)]){const v=structuredClone(out);edit(v);assert.throws(()=>executionReportResult(v,a));}
