test('ambiguous POST response is recovered by GET with no second stock effect or POST',async()=>{
 const p=await prepared(),a=await attempt(p),s=storage(),ownJournal=createExecutionReportJournal(s,context),globalJournal=createWorkspaceRecoveryJournal({getStorage:()=>s,now:()=>123}),handlers=createFieldHandlers({verify:async()=>p.f.session('worker'),operations:p.f.operations});ownJournal.reserve(a);let posts=0,gets=0;
 const transport=createWorkspaceRequestLifecycle(async()=>'synthetic-session',{journal:globalJournal,fetchImpl:async(url,opts)=>{const headers=new Headers(opts.headers);headers.set('origin','https://obrasaas.com');const request=new Request('https://obrasaas.com'+url,{...opts,headers});if(opts.method==='POST'){posts++;const result=await handlers.POST(request),body=await result.json();return Response.json({...body,requestDigest:'f'.repeat(64)});}gets++;return handlers.GET(request);}}),endpoint='/api/identity/field-operations',consume=async response=>executionValidatedResponse(await response.json(),value=>executionReportResult(value,a));
 await assert.rejects(transport.request(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(a.command)},consume));assert.equal(posts,1);assert.equal(p.f.movements().length,1);assert.equal((await globalJournal.list(context.scope)).length,1);assert.deepEqual(ownJournal.read(),a);
 const value=await transport.request(endpoint+'?'+new URLSearchParams({...context,operationId:a.command.operationId}),{},consume);assert.equal(value.state,'RECORDED');ownJournal.clear(a);assert.equal(posts,1);assert.equal(gets,1);assert.equal(p.f.movements().length,1);assert.equal((await globalJournal.list(context.scope)).length,0);assert.equal(ownJournal.read(),null);transport.abort();
});
