// Exercise the actual report component and its event handlers. Like the existing
// evidence-picker and PlanLink harnesses, hooks are scheduled deterministically;
// this is component evidence, not a browser, Clerk or PostgreSQL acceptance run.
import {readFileSync} from 'node:fs';
import {loadBindings,transform} from 'next/dist/build/swc/index.js';
import {renderToStaticMarkup} from 'react-dom/server';
const reportUiRoot=new URL('../src/app/(identity)/cuenta/',import.meta.url);
const reportUiViewUrl=new URL('../src/app/(identity)/cuenta/field-execution-report-view.mjs',import.meta.url).href;
const reportUiSource=readFileSync(new URL('field-execution-report-panel.js',reportUiRoot),'utf8').replace(/^import \{useEffect,useLayoutEffect,useRef,useState\} from 'react';\r?\n/m,'').replace(/^import \{useWorkspaceRequest\} from '[^']+';\r?\n/m,'').replace(/^import \{ConsumptionEvidencePicker\} from '[^']+';\r?\n/m,'').replace(/^import styles from '[^']+';\r?\n/m,'').replace(/(from\s+)(['"])(\.\/?[^'"\n]+)\2/g,(_all,prefix,_quote,specifier)=>prefix+JSON.stringify(specifier==='./field-execution-report-view.mjs'?reportUiViewUrl:new URL(specifier,reportUiRoot).href));
const reportUiHooks=`let fixture={},states=[],refs=[],effects=[],queue=[],stateCursor=0,refCursor=0,effectCursor=0;
const useState=initial=>{const index=stateCursor++;if(!(index in states))states[index]=initial;return[states[index],value=>{states[index]=typeof value==='function'?value(states[index]):value;}];};
const useRef=initial=>{const index=refCursor++;return refs[index]??(refs[index]={current:initial});};
function effect(callback,deps,layout){const index=effectCursor++,old=effects[index];if(!old||!deps||deps.some((value,i)=>!Object.is(value,old.deps?.[i])))queue.push({index,callback,deps,layout,old});}
const useEffect=(callback,deps)=>effect(callback,deps,false),useLayoutEffect=(callback,deps)=>effect(callback,deps,true),useWorkspaceRequest=()=>fixture.request,window={get sessionStorage(){return fixture.storage;}},styles=new Proxy({},{get:(_,key)=>key});
function ConsumptionEvidencePicker(){return null;}
export function unmountReport(){for(const item of effects)item?.cleanup?.();effects=[];queue=[];}
export function resetReport(next){unmountReport();fixture=next;states=[];refs=[];effects=[];queue=[];}
export function renderReport(props){stateCursor=0;refCursor=0;effectCursor=0;const tree=ReportInner(props),pending=queue;queue=[];for(const item of [...pending.filter(item=>item.layout),...pending.filter(item=>!item.layout)]){item.old?.cleanup?.();effects[item.index]={deps:item.deps,cleanup:item.callback()};}return tree;}
`;
await loadBindings();
const reportUiCompiled=await transform(`import React from ${JSON.stringify(import.meta.resolve('react'))};${reportUiHooks}${reportUiSource}`,{filename:'actual-execution-report-component.js',jsc:{parser:{syntax:'ecmascript',jsx:true},target:'es2022',transform:{react:{runtime:'classic'}}},module:{type:'es6'}});
const reportUi=await import('data:text/javascript;base64,'+Buffer.from(reportUiCompiled.code).toString('base64'));
const uiText=node=>[node?.props?.children].flat(Infinity).filter(value=>typeof value==='string').join('');
function uiNodes(tree,predicate){const result=[];function walk(value){if(!value||typeof value!=='object')return;if(predicate(value))result.push(value);for(const child of [value.props?.children].flat(Infinity))walk(child);}walk(tree);return result;}
const settleUi=()=>new Promise(resolve=>setImmediate(resolve));
async function setupReportUi({measured=false,manager=false,sharedStorage=null,snapshotScope=null}={}){
 const f=fieldExecutionFixture({measured});if(manager){f.state.worker.metadata.participant.clerkUserId='user_Owner';f.state.worker.metadata.participant.kyc.review.actorId='director';f.state.evidence.metadata.fieldOperations.recordedBy='owner';f.state.evidence.metadata.fieldOperations.review.actorId='director';}
 const actor=manager?'owner':'worker',issued=await f.issue(manager?'director':'owner'),state={f,actor,issued,storage:sharedStorage||storage(),posts:[],gets:[],pending:[],taskBusy:[],holdPost:false,losePost:false,holdView:false,viewReady:false,postReady:false};
 let postCommitted;state.postCommitted=new Promise(resolve=>{postCommitted=resolve;});
 const realNow=Date.now;Date.now=()=>Date.parse(f.state.now);state.restoreClock=()=>{Date.now=realNow;};
 const handlers=createFieldHandlers({verify:async()=>f.session(actor),operations:f.operations}),globalJournal=createWorkspaceRecoveryJournal({getStorage:()=>state.storage,now:()=>123});
 state.transport=createWorkspaceRequestLifecycle(async()=>'synthetic-report-ui-token',{journal:globalJournal,fetchImpl:async(url,options={})=>{const headers=new Headers(options.headers);headers.set('origin','https://obrasaas.com');const req=new Request('https://obrasaas.com'+url,{...options,headers});if(options.method==='POST'){state.posts.push(JSON.parse(options.body));const response=await handlers.POST(req),held=state.holdPost?new Promise(resolve=>{state.releasePost=resolve;}):null;state.postReady=true;if(response.ok)postCommitted();if(held)await held;if(state.losePost)throw Error('SYNTHETIC_RESPONSE_LOST_AFTER_COMMIT');return response;}state.gets.push(url);const readUrl=new URL(req.url);if(snapshotScope&&readUrl.searchParams.has('executionView'))readUrl.searchParams.set('scope',context.scope);let response=await handlers.GET(new Request(readUrl,{headers}));if(snapshotScope&&readUrl.searchParams.has('executionView')){const body=await response.json();response=Response.json({...body,scope:snapshotScope});}if(readUrl.searchParams.has('executionView')){state.viewReady=true;if(state.holdView)await new Promise(resolve=>{state.releaseView=resolve;});}return response;}});
 state.props={...context,...(snapshotScope?{scope:snapshotScope}:{}),active:true,selfWorkers:own,tasks:[f.state.task],taskPaging:{loading:false,nextCursor:null},getSessionToken:async()=>'synthetic-report-ui-token',onPending:value=>state.pending.push(value),onTaskReadBusy:value=>state.taskBusy.push(value)};
 state.mount=()=>{reportUi.resetReport({storage:state.storage,request:(...args)=>state.transport.request(...args)});state.render();};
 state.render=()=>reportUi.renderReport(state.props);state.html=()=>renderToStaticMarkup(state.render());
 state.button=name=>{const matches=uiNodes(state.render(),node=>node.type==='button'&&uiText(node)===name);assert.equal(matches.length,1,'Expected one UI button '+name);return matches[0];};
 state.click=async name=>{const button=state.button(name);assert.notEqual(button.props.disabled,true,'UI button is disabled: '+name);return button.props.onClick?.({preventDefault(){}});};
 state.field=name=>{const matches=uiNodes(state.render(),node=>node.type==='label'&&uiText(node)===name);assert.equal(matches.length,1,'Expected one UI field '+name);const inputs=uiNodes(matches[0],node=>['input','textarea','select'].includes(node.type));assert.equal(inputs.length,1);return inputs[0];};
 state.fill=(name,value)=>{const field=state.field(name);assert.notEqual(field.props.disabled,true);field.props.onChange({target:{value}});state.render();};
 state.toggle=(name,checked)=>{const field=state.field(name);assert.notEqual(field.props.disabled,true);field.props.onChange({target:{checked}});state.render();};
 state.picker=()=>{const matches=uiNodes(state.render(),node=>node.type?.name==='ConsumptionEvidencePicker');assert.equal(matches.length,1);return matches[0];};
 state.wait=async predicate=>{for(let i=0;i<100;i++){if(predicate())return;await settleUi();}assert.fail('UI operation did not reach its expected boundary');};
 state.load=async()=>{await state.click('Consultar mis autorizaciones');state.render();};
 state.prepare=async()=>{await state.click('Registrar consumo');state.fill('Material','material-a');state.fill('Cantidad utilizada','1.001');state.fill('Qué se realizó','Cantidades declaradas desde la pantalla real.');const form=uiNodes(state.render(),node=>node.type==='form')[0];await form.props.onSubmit({preventDefault(){}});state.render();};
 state.close=()=>{reportUi.unmountReport();state.transport.abort();state.restoreClock();};
 state.mount();await settleUi();state.render();return state;
}

test('actual report UI offers only the own authorization for worker and an admin reporting under another account',async t=>{
 for(const manager of [false,true]){const s=await setupReportUi({manager});try{assert.equal(s.posts.length,0);assert.equal(s.gets.length,0);await s.load();assert.match(s.html(),/Tarea sintética/);assert.equal(s.button('Registrar consumo').props.disabled,false);await s.prepare();assert.match(s.html(),/Al registrar se descontarán/);assert.equal(s.posts.length,0);await s.click('Registrar consumo');s.render();assert.equal(s.posts.length,1);assert.equal(s.posts[0].payload.workerId,'w-worker');assert.equal(s.f.movements().length,1);assert.match(s.html(),/Ejecución registrada/);assert.equal(s.f.state.project.metadata.materialInventory.materials[0].balance,'8.999');}finally{s.close();}}
 const s=await setupReportUi({manager:true});t.after(s.close);s.props.selfWorkers=[{id:'foreign-worker',name:'Otra ficha',canReport:true}];await s.load();assert.doesNotMatch(s.html(),/Tarea sintética/);assert.match(s.html(),/No hay autorizaciones de tu ficha/);assert.equal(s.posts.length,0);
});
