const useEffect=(fn,deps)=>schedule(fn,deps,false),useLayoutEffect=(fn,deps)=>schedule(fn,deps,true),useWorkspaceRequest=()=>bridge.request;
const styles=new Proxy({},{get:(_,name)=>name}),window={get sessionStorage(){return bridge.storage;},addEventListener:(name,fn)=>bridge.listeners.set(name,fn),removeEventListener:name=>bridge.listeners.delete(name)};
const useWorksiteLiveRefresh=()=>({status:{state:'IDLE',checkedAt:null,updates:false},check(){throw Error('Live refresh controller is independently tested outside this parent integration');}}),WorksiteLiveRefreshStatus=()=>null,FieldMediaPreview=()=>null,ExecutionMandatePanel=()=>null;
function expand(value,path){if(Array.isArray(value))return value.map((v,i)=>expand(v,path+'/'+i));if(!value||typeof value!=='object'||!value.type)return value;const id=path+'/'+(typeof value.type==='function'?value.type.name:String(value.type))+':'+(value.key??'');if(typeof value.type==='function'){let s=slots.get(id);if(!s){s={id,states:[],setters:[],refs:[],effects:[]};slots.set(id,s);}used.add(id);Object.assign(s,{cursor:0,refCursor:0,effectCursor:0,idCursor:0});const prior=current;current=s;let tree;try{tree=value.type(value.props);}finally{current=prior;}return expand(tree,id);}return React.cloneElement(value,undefined,expand(value.props.children,id));}
