export function resetInventory(next){unmountInventory();bridge=next;}
export function renderInventory(props){let tree;for(let n=0;n<20;n++){dirty=false;used=new Set();pendingEffects=[];tree=expand(React.createElement(MaterialInventoryPanel,props),'root');for(const[id,s]of slots)if(!used.has(id)){for(const item of s.effects)item?.cleanup?.();slots.delete(id);}const queue=pendingEffects;pendingEffects=[];for(const item of [...queue.filter(row=>row.layout),...queue.filter(row=>!row.layout)]){item.old?.cleanup?.();item.s.effects[item.i]={deps:item.deps,cleanup:item.callback()};}if(!dirty)return tree;}throw Error('Actual parent integration did not settle');}
