async function restoreFixtureAttempt(s,{committed=false}={}){
 const snapshot=await s.f.operations.executionView(s.f.session(s.actor),context),fields={mandateId:s.issued.mandate.id,lines:[{materialId:'material-a',quantity:'1'}],progress:null,evidenceIds:[],reason:'Informe anterior propio, conservado antes de otra preparaciÃ³n.'},payload=prepareExecutionReport(fields,snapshot,own,[s.f.state.task],{reportId:randomUUID(),now:Date.parse(s.f.state.now)}),command=executionReportCommand(payload,{...context,operationId:randomUUID(),confirmed:true}),prior={version:1,command,requestDigest:await executionReportDigest(command)},journal=createExecutionReportJournal(s.storage,context);
 if(committed)await s.f.operations.save(s.f.session(s.actor),command);journal.reserve(prior);return {prior,journal};
}
function controlledRestoreDigest(){
 const descriptor=Object.getOwnPropertyDescriptor(globalThis,'crypto'),original=globalThis.crypto;let enter,release=null,completion=null;const entered=new Promise(resolve=>enter=resolve);
 Object.defineProperty(globalThis,'crypto',{configurable:true,value:{randomUUID:()=>original.randomUUID(),subtle:{digest:(...args)=>new Promise((resolve,reject)=>{assert.equal(release,null,'Only the restored attempt digest may be pending');release=()=>{const result=original.subtle.digest(...args);result.then(resolve,reject);return result;};enter();})}}});
 const restore=()=>{Object.defineProperty(globalThis,'crypto',descriptor);if(release&&!completion)completion=release();return completion;};
 return {entered,restore,async release(){assert.equal(typeof release,'function');if(!completion)completion=release();await completion;restore();await settleUi();}};
}

test('actual Inventory fences report restoration before another draft and preserves its canonical receipt', {timeout:5000}, async t=>{
 const s=await setupInventoryUi();t.after(s.cclose);const {prior,journal}=await restoreFixtureAttempt(s,{committed:true}),gate=controlledRestoreDigest();t.after(gate.restore);
 await s.cclick('Abrir inventario','inventory');await gate.entered;s.crender();
 assert.equal(s.cbutton('Proponer consumo','inventory').props.disabled,true);assert.equal(s.cbutton('Consultar mis autorizaciones').props.disabled,true);assert.equal(s.pendingState.at(-1),true);assert.equal(s.taskBusyState.at(-1),true);assert.deepEqual(journal.read(),prior);assert.equal(s.posts.length,0);
 await gate.release();s.crender();assert.equal(s.cbutton('Comprobar el recibo').props.disabled,false);assert.equal(s.cbutton('Proponer consumo','inventory').props.disabled,true);await s.cclick('Comprobar el recibo');assert.equal(journal.read(),null);assert.equal(s.posts.length,0);assert.equal(s.f.movements().length,1);
 await s.cclick('Proponer consumo','inventory');s.cfill('Cantidad utilizada','2.000','inventory');assert.equal(s.cfield('Cantidad utilizada','inventory').props.value,'2.000');assert.equal(s.cbutton('Volver','inventory').props.disabled,false);
});

